export function errorMetrics(errors: number[]) {
  if (!errors.length) return { rmse: null, mae: null };
  let squared = 0;
  let absolute = 0;
  for (const e of errors) {
    squared += e * e;
    absolute += Math.abs(e);
  }
  return { rmse: Math.sqrt(squared / errors.length), mae: absolute / errors.length };
}
export function real(v: number | null): string {
  if (v === null) return '-';
  if (Math.abs(v) >= 1e21) return BigInt(v).toString() + '.0000';
  const text = v.toFixed(4);
  return +text === 0 ? '0.0000' : text;
}
